command:
cd ~/quartet && cat > probe.js <<'EOF'
const ABCJS = require('./abcjs-basic-min.js');
const hdr = `X:1
T:test
M:4/4
L:1/8
Q:1/4=60
%%score [1 2]
V:1 clef=treble name="Violino I"
V:2 clef=alto name="Viola"
K:Dm
`;
const variants = {
A: hdr + `[V:1] [I:MIDI program 40] A4 d4 |]\n[V:2] [I:MIDI program 42] D,8 |]\n`,
B: hdr + `V:1\n%%MIDI program 40\nA4 d4 |]\nV:2\n%%MIDI program 42\nD,8 |]\n`,
C: hdr + `[V:1] A4 d4 |\n[V:2] D,8 |\n[V:1] A4 d4 |]\n[V:2] D,8 |]\n`,
};
for (const [k, abc] of Object.entries(variants)) {
const t = ABCJS.parseOnly(abc)[0];
if (t.warnings) console.log(t.warnings);
const seq = t.setUpAudio(k==='C'?{program:48}:{});
console.log(k, seq.tracks.map(tr=>tr.filter(e=>e.cmd!=='note').map(e=>JSON.stringify(e)).join(' ')+' notes:'+tr.filter(e=>e.cmd==='note').length).join(' || '));
}
EOF
node probe.js 2>&1 | cut -c1-2500

