<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Quartet desk</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Old+Standard+TT:ital,wght@0,400;0,700;1,400&display=swap" rel="stylesheet">
<style>
  :root {
    --cover: #8fa5b2;      /* urtext-edition blue-grey */
    --cover-deep: #7b93a1;
    --ink: #17232b;
    --paper: #fbfaf5;
    --rosin: #b8741a;      /* playback cursor, active states */
    --graphite: #4d575e;
    --rule: rgba(23, 35, 43, .28);
    --serif: "Old Standard TT", "Century Schoolbook", "Times New Roman", serif;
  }
  * { box-sizing: border-box; }
  html, body { margin: 0; background: var(--cover); color: var(--ink); }
  body { font-family: var(--serif); font-size: 16px; line-height: 1.45; }
  button, select, input, textarea { font: inherit; color: inherit; }

  .desk { max-width: 1180px; margin: 0 auto; }

  /* ---- cover ---- */
  .cover { padding: 26px 22px 18px; text-align: center; }
  .cover .composer { font-size: 15px; letter-spacing: .32em; text-transform: uppercase; margin: 0 0 10px; padding-left: .32em; }
  .cover h1 { font-weight: 400; font-size: clamp(28px, 5.2vw, 46px); line-height: 1.08; margin: 0; letter-spacing: .01em; }
  .cover .movement { font-style: italic; font-size: clamp(17px, 2.6vw, 21px); margin: 8px 0 0; }
  .cover .rule { width: 64px; height: 0; border-top: 1px solid var(--ink); margin: 14px auto 12px; }
  .cover .note { font-size: 15px; max-width: 62ch; margin: 0 auto; color: var(--ink); }
  .contents { display: flex; flex-wrap: wrap; gap: 6px 18px; justify-content: center; margin: 14px 0 0; padding: 0; list-style: none; }
  .contents button { background: none; border: 0; border-bottom: 1px solid transparent; padding: 2px 0; cursor: pointer; font-size: 16px; }
  .contents button[aria-current="true"] { border-bottom-color: var(--ink); font-weight: 700; }
  .contents button:hover { border-bottom-color: var(--ink); }

  /* ---- transport ---- */
  .transport { background: var(--ink); color: var(--paper); padding: 12px 16px 12px; display: grid; grid-template-columns: auto 1fr; gap: 10px 16px; align-items: center; }
  .play { width: 54px; height: 54px; border-radius: 50%; border: 1.5px solid var(--paper); background: transparent; color: var(--paper); cursor: pointer; display: grid; place-items: center; padding: 0; }
  .play:hover { background: rgba(251, 250, 245, .12); }
  .play svg { width: 22px; height: 22px; fill: currentColor; }
  .play[data-state="loading"] { border-style: dashed; cursor: progress; }
  @media (prefers-reduced-motion: no-preference) {
    .play[data-state="loading"] { animation: turn 2.4s linear infinite; }
    @keyframes turn { to { transform: rotate(360deg); } }
  }
  .seek { display: grid; grid-template-columns: 1fr; gap: 3px; min-width: 0; }
  .seek-top { display: flex; justify-content: space-between; gap: 12px; font-size: 15px; font-variant-numeric: tabular-nums; }
  .seek-top .status { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-style: italic; }
  input[type=range] { -webkit-appearance: none; appearance: none; width: 100%; height: 18px; background: transparent; margin: 0; cursor: pointer; }
  input[type=range]::-webkit-slider-runnable-track { height: 2px; background: currentColor; opacity: .55; }
  input[type=range]::-moz-range-track { height: 2px; background: currentColor; opacity: .55; }
  input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; width: 12px; height: 12px; border-radius: 50%; background: var(--rosin); border: 1.5px solid var(--paper); margin-top: -5px; }
  input[type=range]::-moz-range-thumb { width: 10px; height: 10px; border-radius: 50%; background: var(--rosin); border: 1.5px solid var(--paper); }
  .options { grid-column: 1 / -1; display: flex; flex-wrap: wrap; gap: 8px 22px; align-items: center; font-size: 15px; border-top: 1px solid rgba(251, 250, 245, .25); padding-top: 10px; }
  .options label { display: inline-flex; align-items: center; gap: 7px; }
  .options select { background: var(--ink); color: var(--paper); border: 1px solid rgba(251, 250, 245, .5); border-radius: 0; padding: 2px 6px; }
  .options .tempo input { width: 120px; }
  .options .tempo output { min-width: 3.2em; font-variant-numeric: tabular-nums; }
  .parts { display: inline-flex; gap: 0; border: 1px solid rgba(251, 250, 245, .5); }
  .parts button { background: transparent; color: var(--paper); border: 0; border-left: 1px solid rgba(251, 250, 245, .5); padding: 2px 9px; cursor: pointer; }
  .parts button:first-child { border-left: 0; }
  .parts button[aria-pressed="false"] { text-decoration: line-through; opacity: .5; }
  :focus-visible { outline: 2px solid var(--rosin); outline-offset: 2px; }

  /* ---- score ---- */
  .sheet { background: var(--paper); height: 620px; overflow-y: auto; overflow-x: hidden; position: relative; padding: 6px 10px 40px; scroll-behavior: smooth; }
  .sheet svg { display: block; }
  .sheet .abcjs-cursor { stroke: var(--rosin); stroke-width: 2.5; opacity: .85; }
  .sheet .on { fill: var(--rosin); stroke: var(--rosin); }
  .sheet .abcjs-note, .sheet .abcjs-rest { cursor: pointer; }
  .warn { background: var(--paper); border-top: 1px solid var(--rule); padding: 8px 14px; font-size: 15px; white-space: pre-wrap; }
  .warn:empty { display: none; }

  /* ---- source ---- */
  .source { padding: 14px 18px 22px; font-size: 15px; }
  .source summary { cursor: pointer; }
  .source p { max-width: 70ch; margin: 10px 0; }
  .source textarea { width: 100%; height: 320px; background: var(--paper); border: 1px solid var(--ink); border-radius: 0; padding: 10px; font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace; font-size: 13px; line-height: 1.4; white-space: pre; resize: vertical; }
  .source .links { display: flex; flex-wrap: wrap; gap: 6px 20px; margin-top: 8px; }
  .source .links button { background: none; border: 0; border-bottom: 1px solid var(--ink); padding: 0; cursor: pointer; }
  .source .links a { color: inherit; }

  @media (max-width: 520px) {
    .cover { padding: 18px 14px 14px; }
    .sheet { height: 520px; padding: 4px 2px 30px; }
    .options .tempo input { width: 90px; }
  }
</style>
</head>
<body>
<div class="desk">
  <header class="cover">
    <p class="composer" id="composer"></p>
    <h1 id="title"></h1>
    <p class="movement" id="movement"></p>
    <div class="rule"></div>
    <p class="note" id="note"></p>
    <ul class="contents" id="contents"></ul>
  </header>

  <section class="transport" aria-label="Playback">
    <button class="play" id="play" data-state="stopped" aria-label="Play">
      <svg viewBox="0 0 24 24" aria-hidden="true"><path id="playIcon" d="M7 4l14 8-14 8z"/></svg>
    </button>
    <div class="seek">
      <div class="seek-top"><span class="status" id="status">Press play. The first time, the instrument samples take a few seconds to load.</span><span id="clock">0:00 / 0:00</span></div>
      <input type="range" id="seek" min="0" max="1000" value="0" aria-label="Position">
    </div>
    <div class="options">
      <label class="tempo">Tempo <input type="range" id="tempo" min="50" max="130" step="5" value="100"><output id="tempoOut">100%</output></label>
      <label>Sound
        <select id="sound">
          <option value="solo">Solo strings</option>
          <option value="section">String section</option>
          <option value="piano">Piano reduction</option>
        </select>
      </label>
      <span class="parts" id="parts" role="group" aria-label="Parts"></span>
    </div>
  </section>

  <main class="sheet" id="sheet"><div id="paper"></div></main>
  <div class="warn" id="warn"></div>
  <div id="synthHost" hidden></div>

  <details class="source">
    <summary>Source in ABC notation (editable)</summary>
    <p>This is the whole score as text. Edit it and the page re-engraves; press play to hear the change.</p>
    <textarea id="abc" spellcheck="false" aria-label="ABC source"></textarea>
    <div class="links">
      <button id="dlAbc">Download .abc</button>
      <button id="dlMidi">Download MIDI</button>
      <button id="reset">Undo my edits</button>
    </div>
  </details>
</div>

<!--PIECES-->

<script src="https://cdn.jsdelivr.net/npm/abcjs@6.5.2/dist/abcjs-basic-min.js"></script>
<script>
(function () {
  "use strict";
  var SOUNDFONT = "https://paulrosen.github.io/midi-js-soundfonts/abcjs/";
  var SOUNDS = { solo: [40, 40, 41, 42], section: [48, 48, 48, 48], piano: [0, 0, 0, 0] };
  var PART_NAMES = ["Vl. I", "Vl. II", "Vla.", "Vc."];
  var PLAY = "M7 4l14 8-14 8z", PAUSE = "M6 4h4v16H6zM14 4h4v16h-4z";
  var $ = function (id) { return document.getElementById(id); };

  var pieces = Array.prototype.map.call(document.querySelectorAll("script.piece"), function (s) {
    return { id: s.dataset.id, label: s.dataset.label, note: s.dataset.note || "", abc: s.textContent.replace(/^\n/, "") };
  });
  var current = null, visualObj = null, synthControl = null, cursorLine = null, lit = [];
  var partsOn = [true, true, true, true];
  var state = "stopped";       // stopped | loading | playing | paused
  var audioStale = true;       // tune must be (re)loaded into the synth before playing
  var totalSeconds = 0, dragging = false, lastTop = null;

  function field(abc, key) {
    var out = [], re = new RegExp("^" + key + ":\\s*(.*)$", "gm"), m;
    while ((m = re.exec(abc))) out.push(m[1].trim());
    return out;
  }
  function fmt(s) { s = Math.max(0, Math.round(s)); return Math.floor(s / 60) + ":" + ("0" + (s % 60)).slice(-2); }
  function setStatus(t) { $("status").textContent = t; }
  function setState(s) {
    state = s;
    var b = $("play");
    b.dataset.state = s;
    b.setAttribute("aria-label", s === "playing" ? "Pause" : "Play");
    $("playIcon").setAttribute("d", s === "playing" ? PAUSE : PLAY);
  }

  /* ---------- engraving ---------- */
  function engrave() {
    var abc = $("abc").value;
    var titles = field(abc, "T");
    $("title").textContent = titles[0] || "Untitled";
    $("movement").textContent = titles.slice(1).join(" \u2014 ");
    $("composer").textContent = field(abc, "C")[0] || "";
    // The cover shows title and composer, so keep them off the sheet. Blank them
    // in place (same length) so character positions still match the textarea.
    var body = abc.replace(/^([TC]):.*$/gm, function (line, k) { return k === "T" ? "T:" + Array(line.length - 1).join(" ") : "%" + Array(line.length).join(" "); });
    var w = Math.max($("sheet").clientWidth - 24, 520);
    var out = ABCJS.renderAbc("paper", body, {
      responsive: "resize", add_classes: true, staffwidth: w,
      wrap: { minSpacing: 1.5, maxSpacing: 2.6, preferredMeasuresPerLine: w > 900 ? 5 : w > 640 ? 4 : 3 },
      paddingtop: 0, paddingbottom: 10, paddingleft: 6, paddingright: 6,
      foregroundColor: "#17232b", selectionColor: "#17232b",
      clickListener: onNoteClick,
      format: { vocalfont: "Old Standard TT 13", annotationfont: "Old Standard TT italic 13", tempofont: "Old Standard TT bold 14", voicefont: "Old Standard TT italic 13", measurefont: "Old Standard TT italic 11", partsfont: "Old Standard TT bold 15" }
    });
    visualObj = out[0];
    var warnings = (visualObj && visualObj.warnings) || [];
    $("warn").textContent = warnings.length ? "Notation problems:\n" + warnings.map(function (x) { return x.replace(/<[^>]+>/g, ""); }).join("\n") : "";
    var svg = document.querySelector("#paper svg");
    cursorLine = null; lit = []; lastTop = null;
    if (svg) {
      cursorLine = document.createElementNS("http://www.w3.org/2000/svg", "line");
      cursorLine.setAttribute("class", "abcjs-cursor");
      svg.appendChild(cursorLine);
    }
    audioStale = true;
  }

  /* ---------- playback ---------- */
  var cursorControl = {
    onStart: function () { },
    onBeat: function (beat, totalBeats, totalMs) {
      totalSeconds = totalMs / 1000;
      if (!dragging && totalBeats) $("seek").value = Math.round(1000 * beat / totalBeats);
      $("clock").textContent = fmt(totalSeconds * beat / (totalBeats || 1)) + " / " + fmt(totalSeconds);
    },
    onEvent: function (ev) {
      if (!ev || (ev.measureStart && ev.left === null)) return;
      lit.forEach(function (el) { el.classList.remove("on"); });
      lit = [];
      (ev.elements || []).forEach(function (group) { Array.prototype.forEach.call(group, function (el) { el.classList.add("on"); lit.push(el); }); });
      if (cursorLine) {
        cursorLine.setAttribute("x1", ev.left - 3); cursorLine.setAttribute("x2", ev.left - 3);
        cursorLine.setAttribute("y1", ev.top); cursorLine.setAttribute("y2", ev.top + ev.height);
        if (ev.top !== lastTop) { lastTop = ev.top; follow(); }
      }
      if (ev.measureNumber != null && state === "playing") setStatus("Bar " + (ev.measureNumber + 1));
    },
    onFinished: function () {
      lit.forEach(function (el) { el.classList.remove("on"); }); lit = [];
      if (cursorLine) { cursorLine.setAttribute("y1", 0); cursorLine.setAttribute("y2", 0); }
      setState("stopped"); setStatus("Fine."); $("seek").value = 0;
    }
  };
  function follow() {
    var sheet = $("sheet"), r = cursorLine.getBoundingClientRect(), s = sheet.getBoundingClientRect();
    var target = sheet.scrollTop + (r.top - s.top) - 24;
    if (Math.abs(target - sheet.scrollTop) > 8) sheet.scrollTo({ top: Math.max(0, target) });
  }
  function audioParams() {
    var programs = SOUNDS[$("sound").value] || SOUNDS.solo;
    var off = [];
    partsOn.forEach(function (on, i) { if (!on) off.push(i); });
    return {
      soundFontUrl: SOUNDFONT,
      voicesOff: off.length ? off : false,
      sequenceCallback: function (tracks) {
        tracks.forEach(function (track, i) {
          var p = programs[Math.min(i, programs.length - 1)];
          track.forEach(function (e) { if ("instrument" in e) e.instrument = p; });
        });
        return tracks;
      }
    };
  }
  function ensureSynth() {
    if (synthControl) return;
    synthControl = new ABCJS.synth.SynthController();
    synthControl.load("#synthHost", cursorControl, { displayPlay: true, displayProgress: true, displayWarp: true, displayRestart: true });
  }
  function loadAudio() {
    ensureSynth();
    setState("loading"); setStatus("Loading the instruments\u2026");
    return synthControl.setTune(visualObj, true, audioParams()).then(function () {
      audioStale = false;
      var warp = +$("tempo").value;
      return warp === 100 ? null : synthControl.setWarp(warp);
    });
  }
  function fail(err) {
    setState("stopped");
    setStatus("Could not start the sound: " + (err && err.message ? err.message : err));
    if (window.console) console.error(err);
  }
  function togglePlay() {
    if (!ABCJS.synth.supportsAudio()) { setStatus("This browser has no Web Audio, so the score is silent here."); return; }
    if (state === "loading") return;
    if (state === "playing") { synthControl.pause(); setState("paused"); setStatus("Paused."); return; }
    var go = function () { return Promise.resolve(synthControl.play()).then(function () { setState("playing"); }); };
    (audioStale ? loadAudio().then(go) : go()).catch(fail);
  }
  function stopForChange() {
    // Anything that changes the sound needs the audio rebuilt on the next play.
    audioStale = true;
    if (synthControl && (state === "playing" || state === "paused")) { try { synthControl.pause(); synthControl.restart(); synthControl.pause(); } catch (e) { } }
    if (state !== "stopped") setStatus("Changed. Press play to hear it.");
    setState("stopped"); $("seek").value = 0;
  }
  function seekTo(fraction) {
    if (!synthControl || audioStale) return;
    synthControl.seek(Math.min(0.999, Math.max(0, fraction)));
  }
  function onNoteClick(abcElem) {
    if (audioStale || !totalSeconds || !abcElem || abcElem.currentTrackMilliseconds == null) return;
    var ms = abcElem.currentTrackMilliseconds;
    if (Array.isArray(ms)) ms = ms[0];
    seekTo(ms / (totalSeconds * 1000));
  }

  /* ---------- library ---------- */
  function openPiece(p) {
    if (state !== "stopped") stopForChange();
    current = p;
    $("abc").value = p.abc;
    $("note").textContent = p.note;
    Array.prototype.forEach.call($("contents").children, function (li) {
      li.firstChild.setAttribute("aria-current", li.firstChild.dataset.id === p.id ? "true" : "false");
    });
    engrave();
    $("sheet").scrollTop = 0;
    $("clock").textContent = "0:00 / 0:00";
    setStatus("Press play. The first time, the instrument samples take a few seconds to load.");
  }
  function download(name, blob) {
    var a = document.createElement("a");
    a.href = URL.createObjectURL(blob); a.download = name;
    document.body.appendChild(a); a.click(); a.remove();
  }

  /* ---------- wiring ---------- */
  if (pieces.length > 1) pieces.forEach(function (p) {
    var li = document.createElement("li"), b = document.createElement("button");
    b.textContent = p.label; b.dataset.id = p.id;
    b.addEventListener("click", function () { openPiece(p); });
    li.appendChild(b); $("contents").appendChild(li);
  });
  PART_NAMES.forEach(function (name, i) {
    var b = document.createElement("button");
    b.textContent = name; b.setAttribute("aria-pressed", "true"); b.title = "Mute or unmute " + name;
    b.addEventListener("click", function () {
      partsOn[i] = !partsOn[i]; b.setAttribute("aria-pressed", String(partsOn[i])); stopForChange();
    });
    $("parts").appendChild(b);
  });
  $("play").addEventListener("click", togglePlay);
  $("sound").addEventListener("change", stopForChange);
  $("tempo").addEventListener("input", function () { $("tempoOut").textContent = this.value + "%"; });
  $("tempo").addEventListener("change", function () {
    if (!synthControl || audioStale) return;
    var was = state;
    setState("loading"); setStatus("Changing the tempo\u2026");
    Promise.resolve(synthControl.setWarp(+this.value)).then(function () {
      // setWarp restarts playback if it was running
      setState(was === "playing" ? "playing" : "stopped"); setStatus(was === "playing" ? "" : "Tempo set. Press play.");
    }).catch(fail);
  });
  $("seek").addEventListener("input", function () { dragging = true; });
  $("seek").addEventListener("change", function () { dragging = false; seekTo(this.value / 1000); });
  var typing = null;
  $("abc").addEventListener("input", function () {
    clearTimeout(typing);
    typing = setTimeout(function () { if (state !== "stopped") stopForChange(); engrave(); }, 400);
  });
  $("reset").addEventListener("click", function () { if (current) openPiece(current); });
  $("dlAbc").addEventListener("click", function () { download((current ? current.id : "score") + ".abc", new Blob([$("abc").value], { type: "text/plain" })); });
  $("dlMidi").addEventListener("click", function () {
    var midi = ABCJS.synth.getMidiFile($("abc").value, { midiOutputType: "binary" });
    download((current ? current.id : "score") + ".mid", new Blob([midi[0]], { type: "audio/midi" }));
  });
  var resizing = null, lastW = 0;
  new ResizeObserver(function () {
    var w = $("sheet").clientWidth;
    if (Math.abs(w - lastW) < 40) return;
    lastW = w; clearTimeout(resizing);
    resizing = setTimeout(function () { if (state === "stopped" && current) engrave(); }, 250);
  }).observe($("sheet"));

  window.quartetDesk = { state: function () { return state; }, synth: function () { return synthControl; } };
  if (pieces.length) { lastW = $("sheet").clientWidth; openPiece(pieces[0]); }
})();
</script>
</body>
</html>

