// Inlines pieces/*.abc into template.html -> dist/player.html
// Each piece file may start with comment lines:  %%label Short name   %%note One-line programme note
const fs = require('fs'), path = require('path');
const dir = path.join(__dirname, 'pieces');
const esc = s => s.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
const blocks = fs.readdirSync(dir).filter(f => f.endsWith('.abc')).sort().map(f => {
  let abc = fs.readFileSync(path.join(dir, f), 'utf8');
  const meta = {};
  abc = abc.replace(/^%%(label|note) (.*)\n/gm, (_, k, v) => { meta[k] = v; return ''; });
  if (abc.includes('</script')) throw new Error(f + ' contains </script');
  const id = f.replace(/\.abc$/, '');
  return `<script type="text/plain" class="piece" data-id="${esc(id)}" data-label="${esc(meta.label || id)}" data-note="${esc(meta.note || '')}">\n${abc}</script>`;
});
const html = fs.readFileSync(path.join(__dirname, 'template.html'), 'utf8').replace('<!--PIECES-->', blocks.join('\n'));
fs.mkdirSync(path.join(__dirname, 'dist'), { recursive: true });
fs.writeFileSync(path.join(__dirname, 'dist/player.html'), html);
console.log('dist/player.html', html.length, 'bytes,', blocks.length, 'piece(s)');

