const { launch } = require('./cdp.js');
(async () => {
  const page = await launch({ width: 1000, height: 1000 });
  try {
    await page.open('http://127.0.0.1:8765/dist/player.html');
    console.log('svg:', await page.eval("document.querySelectorAll('#paper svg').length"), 'warn:', JSON.stringify(await page.eval("document.getElementById('warn').textContent")));
    await page.eval("document.getElementById('play').click()");
    for (let i = 0; i < 20; i++) {
      await page.sleep(1000);
      const s = await page.eval("quartetDesk.state() + ' | ' + document.getElementById('status').textContent + ' | ' + document.getElementById('clock').textContent + ' | lit=' + document.querySelectorAll('.on').length + ' | cursor x=' + (document.querySelector('.abcjs-cursor')||{getAttribute(){return null}}).getAttribute('x1')");
      console.log(i, s);
