content:
// node test-features.js  — exercises every playback control in dist/player.html and prints evidence.
// Live audio is measured with an AnalyserNode tapped onto every buffer source abcjs plays.
const { launch } = require('./cdp.js');
const TAP = `(() => {
  if (window.__tap) return;
  const conn = AudioBufferSourceNode.prototype.connect;
  AudioBufferSourceNode.prototype.connect = function (dest) {
    const ctx = this.context;
    if (!(ctx instanceof OfflineAudioContext)) {
      if (!ctx.__an) { ctx.__an = ctx.createAnalyser(); ctx.__an.fftSize = 2048; const z = ctx.createGain(); z.gain.value = 0; ctx.__an.connect(z); z.connect(ctx.destination); window.__an = ctx.__an; }
      conn.call(this, ctx.__an);
    }
    return conn.apply(this, arguments);
  };
  window.__tap = true;
})()`;
const ST = `(() => {
  const sc = quartetDesk.synth(), mb = sc && sc.midiBuffer, ctx = ABCJS.synth.activeAudioContext && ABCJS.synth.activeAudioContext();
  let audio = '-';
  if (mb && ctx) audio = (mb.isRunning ? ctx.currentTime - mb.startTimeSec : (mb.pausedTimeSec || 0)).toFixed(2) + 's' + (mb.isRunning ? '' : '(idle)');
  let rms = '-';
  if (window.__an) { const d = new Float32Array(2048); __an.getFloatTimeDomainData(d); let s = 0; for (const x of d) s += x * x; rms = Math.sqrt(s / d.length).toFixed(4); }
  const c = document.querySelector('.abcjs-cursor');
  return [quartetDesk.state(), document.getElementById('status').textContent, document.getElementById('clock').textContent,
    'seek=' + document.getElementById('seek').value, 'x=' + (c && c.getAttribute('x1') ? (+c.getAttribute('x1')).toFixed(0) : '-'),
    'audioPos=' + audio, 'liveRms=' + rms].join(' | ');
})()`;
const BUF = `(() => {
  const mb = quartetDesk.synth().midiBuffer, b = mb.audioBuffers[0], d = b.getChannelData(0);
  let pk = 0, s = 0; for (const x of d) { const a = Math.abs(x); if (a > pk) pk = a; s += a * a; }
  const progs = mb.flattened.tracks.map(t => t.filter(e => e.cmd === 'program').map(e => e.instrument).join('/')).join(',');
  return 'buffer ' + b.duration.toFixed(2) + 's peak=' + pk.toFixed(3) + ' rms=' + Math.sqrt(s / d.length).toFixed(4) + ' programs=' + progs;
})()`;
const FETCHED = `[...new Set(performance.getEntriesByType('resource').map(e => e.name).filter(n => /midi-js-soundfonts/.test(n)).map(n => n.split('/').slice(-2, -1)[0]))].join(',')`;

(async () => {
  const page = await launch({ width: 1000, height: 1000, port: 9334 });
  const ev = e => page.eval(e), sleep = ms => page.sleep(ms);
  const log = async (label) => console.log('  ' + label.padEnd(16), await ev(ST));
  const click = id => ev(`document.getElementById('${id}').click()`);
  const setRange = (id, v) => ev(`(() => { const r = document.getElementById('${id}'); r.value = ${v}; r.dispatchEvent(new Event('input', {bubbles: true})); r.dispatchEvent(new Event('change', {bubbles: true})); })()`);
  const waitState = async (s, ms = 30000) => { const t = Date.now(); while (Date.now() - t < ms) { if (await ev('quartetDesk.state()') === s) return true; await sleep(200); } return false; };
  try {
    await page.open('file://quartet/dist/player.html');
    await ev(TAP);

    console.log('\n[1] pause / resume');
    await click('play'); await waitState('playing'); await sleep(3000); await log('playing 3s');
    await click('play'); await sleep(500); await log('paused');
    await sleep(1500); await log('paused +1.5s');
    await click('play'); await sleep(500); await log('resumed');
    await sleep(2000); await log('resumed +2s');

    console.log('\n[2] sound options: rendered buffer, live output, samples fetched');
    for (const s of ['solo', 'section', 'piano']) {
      await ev(`(() => { const e = document.getElementById('sound'); e.value = '${s}'; e.dispatchEvent(new Event('change')); })()`);
      await log('after change');
      await click('play'); await waitState('playing'); await sleep(2500);
      console.log('  ' + s.padEnd(16), await ev(BUF));
      await log('playing');
      await click('play'); await sleep(300);
    }
    console.log('  soundfonts fetched:', await ev(FETCHED));
    await ev(`(() => { const e = document.getElementById('sound'); e.value = 'solo'; e.dispatchEvent(new Event('change')); })()`);

    console.log('\n[3] seek slider while playing, then while paused');
    await click('play'); await waitState('playing'); await sleep(1500); await log('playing');
    await setRange('seek', 500); await sleep(300); await log('seek 50%');
    await sleep(1500); await log('+1.5s');
    await click('play'); await sleep(300); await log('paused');
    await setRange('seek', 250); await sleep(300); await log('seek 25% paused');
    await click('play'); await sleep(1500); await log('resumed +1.5s');

    console.log('\n[4] tempo while playing');
    await setRange('tempo', 50); await waitState('playing'); await sleep(300); await log('tempo 50%');
    await sleep(2000); await log('+2s');
    await setRange('tempo', 100); await waitState('playing'); await sleep(2000); await log('tempo 100% +2s');
    console.log('    tempo while paused');
    await click('play'); await sleep(300); await log('paused');
    await setRange('tempo', 130); await sleep(4000); await log('tempo 130%');
    await click('play'); await sleep(2000); await log('play +2s');
    await click('play'); await sleep(300);

    console.log('\n[5] mute parts');
    await click('play'); await sleep(300);
    await ev(`document.querySelectorAll('#parts button')[0].click()`); await sleep(300); await log('mute Vl.I');
    await click('play'); await waitState('playing'); await sleep(1500); await log('playing');
    console.log('  Vl.I muted     ', await ev(BUF));
    for (const i of [1, 2, 3]) await ev(`document.querySelectorAll('#parts button')[${i}].click()`);
    await click('play'); await waitState('playing'); await sleep(1500);
    console.log('  all muted      ', await ev(BUF)); await log('playing');
    for (const i of [0, 1, 2, 3]) await ev(`document.querySelectorAll('#parts button')[${i}].click()`);
    await click('play'); await waitState('playing'); await sleep(1000);
    console.log('  all on again   ', await ev(BUF));

    console.log('\n[6] tempo while stopped (audio not yet loaded), then click a note');
    await ev(`(() => { const e = document.getElementById('sound'); e.value = 'solo'; e.dispatchEvent(new Event('change')); })()`);
    await setRange('tempo', 70); await log('tempo 70% stop');
    await click('play'); await waitState('playing'); await sleep(1500); await log('playing');
    const r = await ev(`(() => { const n = document.querySelectorAll('#paper .abcjs-v0 .abcjs-note')[12]; n.scrollIntoView({block: 'center'}); const b = n.getBoundingClientRect(); return {x: b.x + b.width / 2, y: b.y + b.height / 2, m: n.getAttribute('class').match(/abcjs-m\\d+/)[0]}; })()`);
    await sleep(800);
    const r2 = await ev(`(() => { const n = document.querySelectorAll('#paper .abcjs-v0 .abcjs-note')[12]; const b = n.getBoundingClientRect(); return {x: b.x + b.width / 2, y: b.y + b.height / 2}; })()`);
    for (const type of ['mousePressed', 'mouseReleased']) await page.send('Input.dispatchMouseEvent', { type, x: r2.x, y: r2.y, button: 'left', clickCount: 1 });
    await sleep(300); await log('clicked ' + r.m);
    await sleep(1500); await log('+1.5s');
    await setRange('tempo', 100); await waitState('playing');

    console.log('\n[7] end of piece, then play again');
    await setRange('seek', 900); await sleep(300); await log('seek 90%');
    await waitState('stopped', 15000); await log('ended');
    await click('play'); await waitState('playing'); await sleep(700); await log('play again');
    await sleep(1500); await log('+1.5s');
  } catch (e) { console.log('ERR', e.message); }
  console.log('\nconsole:', page.logs.slice(0, 20));
  await page.close();
})();

