// node test-envelope.js — render one 4-second note per program through abcjs (CreateSynth.prime)
// for each soundfont variant, and print its amplitude envelope (50 ms RMS windows).
const { launch } = require('./cdp.js');
const FONTS = ['abcjs', 'FluidR3_GM', 'MusyngKite'];
const NOTES = { 40: ['a', 'A4'], 41: ['d', 'D4'], 42: ['D', 'D3'], 48: ['a', 'A4'] };   // ABC pitch, sample name
(async () => {
  const page = await launch({ width: 800, height: 600, port: 9336 });
  try {
    await page.open('file://quartet/dist/player.html');
    console.log('font        prog note  sample_len  t_peak   level vs peak (dB) at 1s / 2s / 3s / 4s   (4.0s note @ Q:1/4=60)');
    for (const font of FONTS) for (const [prog, [abcPitch, name]] of Object.entries(NOTES)) {
      const r = await page.eval(`(async () => {
        const url = 'https://paulrosen.github.io/midi-js-soundfonts/${font}/';
        const vo = ABCJS.parseOnly('X:1\\nL:1/4\\nQ:1/4=60\\nM:4/4\\nK:C\\n%%MIDI program ${prog}\\n${abcPitch}4|]\\n')[0];
        const s = new ABCJS.synth.CreateSynth();
        await s.init({ visualObj: vo, options: { soundFontUrl: url } });
        await s.prime();
        const b = s.audioBuffers[0], d = b.getChannelData(0), sr = b.sampleRate, W = Math.round(sr * 0.05);
        const rms = []; for (let i = 0; i + W <= d.length; i += W) { let q = 0; for (let j = i; j < i + W; j++) q += d[j] * d[j]; rms.push(Math.sqrt(q / W)); }
        let pk = 0, pi = 0; rms.forEach((v, i) => { if (v > pk) { pk = v; pi = i; } });
        const at = t => { const v = rms[Math.min(rms.length - 1, Math.round(t / 0.05) - 1)]; return v > 0 ? (20 * Math.log10(v / pk)).toFixed(1) : '-inf'; };
        const raw = await (await fetch(url + ABCJS.synth.instrumentIndexToName[${prog}] + '-mp3/${name}.mp3')).arrayBuffer();
        const dec = await ABCJS.synth.activeAudioContext().decodeAudioData(raw);
        return { len: dec.duration.toFixed(2) + 's', tpk: (pi * 0.05 + 0.025).toFixed(2) + 's', lv: [1, 2, 3, 4].map(at).join(' / '), peak: pk.toFixed(3) };
      })()`);
      console.log(font.padEnd(11), prog.padEnd(4), name.padEnd(5), r.len.padEnd(11), r.tpk.padEnd(8), r.lv, '  (peak rms ' + r.peak + ')');
    }
  } catch (e) { console.log('ERR', e.message); }
  console.log('console:', page.logs.slice(0, 10));
  await page.close();
})();

