// Structural checks on a quartet in ABC: bar lengths, instrument ranges, harmony per beat, parallel 5ths/8ves.
// usage: node check.js pieces/x.abc [--chords] [--from N --to M]
const ABCJS = require('./abcjs-basic-min.js');
const fs = require('fs');
const args = process.argv.slice(2);
const file = args[0];
const opt = k => { const i = args.indexOf(k); return i < 0 ? null : (args[i + 1] || true); };
const src = fs.readFileSync(file, 'utf8').replace(/^%%(label|note) .*\n/gm, '');
const NAMES = ['C', 'C#', 'D', 'Eb', 'E', 'F', 'F#', 'G', 'G#', 'A', 'Bb', 'B'];
const nn = p => NAMES[p % 12] + (Math.floor(p / 12) - 1);
const VOICES = ['Vl.I', 'Vl.II', 'Vla', 'Vc'];
const LOW = [55, 55, 48, 36], HIGH = [100, 93, 88, 81];
let problems = 0;
const say = s => { problems++; console.log('!! ' + s); };

// 1. parser warnings and bar lengths
const tune = ABCJS.parseOnly(src)[0];
(tune.warnings || []).forEach(w => say('parser: ' + w.replace(/<[^>]+>/g, '')));
const meter = tune.getMeterFraction ? tune.getMeterFraction() : { num: 4, den: 4 };
const barLen = meter.num / meter.den;
const perVoice = {};
tune.lines.forEach(line => (line.staff || []).forEach((st, si) => st.voices.forEach((v, vi) => {
  const key = si + '.' + vi; (perVoice[key] = perVoice[key] || []).push(...v);
})));
const barCounts = [];
Object.keys(perVoice).forEach((key, idx) => {
  let acc = 0, bar = 1, tuplet = null;
  for (const el of perVoice[key]) {
    if (el.el_type === 'note') {
      let d = el.duration;
      if (el.startTriplet) tuplet = { mult: el.tripletMultiplier, left: el.tripletR || el.startTriplet };
      if (tuplet) { d *= tuplet.mult; if (--tuplet.left <= 0) tuplet = null; }
      if (!el.gracenotes || el.pitches || el.rest) acc += d;
    } else if (el.el_type === 'bar') {
      if (acc > 0) {
        if (Math.abs(acc - barLen) > 1e-6 && !(bar === 1 && acc < barLen)) say(`${VOICES[idx] || key} bar ${bar}: length ${acc * 8} eighths, expected ${barLen * 8}`);
        bar++; acc = 0;
      }
    }
  }
  barCounts.push(bar - 1 + (acc > 0 ? 1 : 0));
});
if (new Set(barCounts).size > 1) say('voices have different bar counts: ' + barCounts.join(', '));
console.log('bars per voice:', barCounts.join(', '));

// 2. pitches over time (tempo changes and repeats removed so that 1 bar = barLen exactly)
const flat = src.replace(/\[Q:[^\]]*\]/g, '').replace(/!trill!/g, '').replace(/\|:/g, '|').replace(/:\|/g, '|');
const seq = ABCJS.parseOnly(flat)[0].setUpAudio();
const tracks = seq.tracks.map(t => t.filter(e => e.cmd === 'note'));
tracks.forEach((t, i) => t.forEach(e => {
  if (e.pitch < LOW[i] || e.pitch > HIGH[i]) say(`${VOICES[i]} bar ${Math.floor(e.start / barLen + 1e-6) + 1}: ${nn(e.pitch)} out of range`);
}));
const STEP = 1 / 8;                       // sample every eighth note
const total = Math.max(...tracks.map(t => t.length ? t[t.length - 1].start + t[t.length - 1].duration : 0));
const steps = Math.round(total / STEP);
const grid = tracks.map(t => { const g = new Array(steps).fill(null), on = new Array(steps).fill(false);
  t.forEach(e => { const a = Math.round(e.start / STEP), b = Math.max(a + 1, Math.round((e.start + e.duration) / STEP)); for (let k = a; k < b && k < steps; k++) { if (g[k] === null || e.pitch < g[k]) g[k] = e.pitch; } on[a] = true; });
  return { g, on }; });

// 3. parallel perfect fifths / octaves between consecutive different sonorities
for (let k = 1; k < steps; k++) for (let a = 0; a < 4; a++) for (let b = a + 1; b < 4; b++) {
  const p1 = grid[a].g[k - 1], q1 = grid[b].g[k - 1], p2 = grid[a].g[k], q2 = grid[b].g[k];
  if (p1 == null || q1 == null || p2 == null || q2 == null) continue;
  if (p1 === p2 || q1 === q2) continue;                    // one voice holds or repeats: not parallel motion
  const i1 = Math.abs(p1 - q1) % 12, i2 = Math.abs(p2 - q2) % 12;
  if (i1 === i2 && (i1 === 7 || i1 === 0) && Math.sign(p2 - p1) === Math.sign(q2 - q1) && p1 !== q1) {
    const bar = Math.floor(k * STEP / barLen + 1e-6) + 1, beat = ((k * STEP) % barLen) * 4 + 1;
    // unison/octave doubling that lasts (three or more steps in a row) is deliberate doubling, reported once as info
    const kind = i1 === 7 ? 'fifths' : 'octaves';
    let run = 0; for (let j = k; j < steps && grid[a].g[j] != null && grid[b].g[j] != null && Math.abs(grid[a].g[j] - grid[b].g[j]) % 12 === i1; j++) run++;
    let back = 0; for (let j = k - 1; j >= 0 && grid[a].g[j] != null && grid[b].g[j] != null && Math.abs(grid[a].g[j] - grid[b].g[j]) % 12 === i1; j--) back++;
    const changes = new Set(); for (let j = k - back; j < k + run; j++) changes.add(grid[a].g[j]);
    if (i1 === 0 && changes.size >= 3) continue;           // sustained octave doubling (unison passage)
    say(`parallel ${kind} ${VOICES[a]}/${VOICES[b]} into bar ${bar} beat ${beat}: ${nn(p1)}-${nn(q1)} -> ${nn(p2)}-${nn(q2)}`);
