}

// 4. voice crossing info and chord table
if (opt('--chords')) {
  const from = +(opt('--from') || 1), to = +(opt('--to') || 1e9);
  for (let k = 0; k < steps; k++) {
    const bar = Math.floor(k * STEP / barLen + 1e-6) + 1; if (bar < from || bar > to) continue;
