    const pcs = [...new Set(grid.map(v => v.g[k]).filter(x => x != null).map(x => NAMES[x % 12]))];
    console.log(`${String(bar).padStart(3)}.${(pos / 2 + 1).toFixed(1)}  ${col.join(' ')}  {${pcs.join(' ')}}`);
  }
}
