    if (i1 === 0 && changes.size >= 3) continue;           // sustained octave doubling (unison passage)
    say(`parallel ${kind} ${VOICES[a]}/${VOICES[b]} into bar ${bar} beat ${beat}: ${nn(p1)}-${nn(q1)} -> ${nn(p2)}-${nn(q2)}`);
  }
}

// 4. voice crossing info and chord table
if (opt('--chords')) {
  const from = +(opt('--from') || 1), to = +(opt('--to') || 1e9);
  for (let k = 0; k < steps; k++) {
    const bar = Math.floor(k * STEP / barLen + 1e-6) + 1; if (bar < from || bar > to) continue;
    const pos = Math.round(((k * STEP) % barLen) / STEP);
    const changed = k === 0 || grid.some(v => v.g[k] !== v.g[k - 1]);
    if (!changed && pos % 2) continue;
    if (pos % 2 && !opt('--eighths')) { const strong = grid.filter(v => v.on[k]).length; if (strong < 1) continue; }
    const col = [3, 2, 1, 0].map(i => grid[i].g[k] == null ? '  - ' : nn(grid[i].g[k]).padEnd(4));
    const pcs = [...new Set(grid.map(v => v.g[k]).filter(x => x != null).map(x => NAMES[x % 12]))];
    console.log(`${String(bar).padStart(3)}.${(pos / 2 + 1).toFixed(1)}  ${col.join(' ')}  {${pcs.join(' ')}}`);
  }
}
