    await page.eval("document.getElementById('play').click()");
    for (let i = 0; i < 60; i++) { await page.sleep(500); if (/^playing/.test(await page.eval("quartetDesk.state()"))) break; }
    console.log(await page.eval(`(() => { const b = quartetDesk.synth().midiBuffer.audioBuffers[0]; const out = []; for (let c = 0; c < b.numberOfChannels; c++) { const d = b.getChannelData(c); let pk = 0, sq = 0, over = 0; for (let i = 0; i < d.length; i++) { const a = Math.abs(d[i]); if (a > pk) pk = a; if (a > 1) over++; sq += a*a; } out.push('ch' + c + ' peak=' + pk.toFixed(3) + ' rms=' + Math.sqrt(sq / d.length).toFixed(4) + ' clipped=' + (100 * over / d.length).toFixed(3) + '%'); } return document.getElementById('title').textContent + ' | ' + document.getElementById('clock').textContent + ' | ' + b.duration.toFixed(1) + 's | ' + out.join(' | ') + ' | warn=' + document.getElementById('warn').textContent.slice(0, 200); })()`));
  } catch (e) { console.log('ERR', e.message); }
  if (page.logs.length) console.log('console:', page.logs.slice(0, 5));
  await page.close();
})();
