cd ~/quartet && python3 - <<'EOF'
p='build.js'; s=open(p).read()
helper = r'''
// abcjs redraws the key signature at the start of every source line that follows a mid-tune
// key change. So from the first inline [K:...] on, join each voice's lines into one long line
// per key section; section comments inside are kept in front of the joined block.
function joinAfterKeyChange(abc) {
  const out = [], lines = abc.split('\n');
  let group = null;                      // { comments: [], voices: {n: text} }
  const flush = () => { if (!group) return; out.push(...group.comments); Object.keys(group.voices).sort().forEach(n => out.push(`[V:${n}] ` + group.voices[n])); group = null; };
  for (const line of lines) {
    const m = /^\[V:(\d+)\]\s*(.*)$/.exec(line);
    if (m && /^\[K:/.test(m[2])) { if (m[1] === '1' || !group) { flush(); group = { comments: [], voices: {} }; } group.voices[m[1]] = m[2]; continue; }
    if (!group) { out.push(line); continue; }
    if (m) { group.voices[m[1]] = (group.voices[m[1]] ? group.voices[m[1]] + ' ' : '') + m[2]; continue; }
    if (line.startsWith('%') || !line.trim()) { if (line.trim()) group.comments.push(line); continue; }
    flush(); out.push(line);
  }
  flush();
  return out.join('\n') + (abc.endsWith('\n') ? '\n' : '');
}
'''
s = s.replace("const dir = path.join(__dirname, 'pieces');", helper + "const dir = path.join(__dirname, 'pieces');")
s = s.replace("  if (abc.includes('</script'))", "  abc = joinAfterKeyChange(abc);\n  if (abc.includes('</script'))")
assert 'abc = joinAfterKeyChange(abc);' in s
