// Attack shape of the raw soundfont samples: RMS level (dB vs the sample's peak window) at early times.
const { launch } = require('./cdp.js');
const INST = ['violin', 'viola', 'cello', 'string_ensemble_1', 'tremolo_strings', 'fiddle', 'string_ensemble_2', 'contrabass'];
const NOTES = ['D3', 'A3', 'D4', 'A4', 'D5', 'A5'];
(async () => {
  const page = await launch({ width: 800, height: 600, port: 9337 });
  try {
    await page.open('file://quartet/dist/player.html');
    console.log('instrument note  len    dB at 0.05 0.10 0.15 0.20 0.30 0.50 1.00 s   peak_rms');
    for (const inst of INST) for (const note of NOTES) {
      const r = await page.eval(`(async () => {
        try {
          const raw = await (await fetch('https://paulrosen.github.io/midi-js-soundfonts/abcjs/${inst}-mp3/${note}.mp3')).arrayBuffer();
          const ctx = new (window.AudioContext || window.webkitAudioContext)();
          const b = await ctx.decodeAudioData(raw); const d = b.getChannelData(0), sr = b.sampleRate, W = Math.round(sr * 0.05);
          const rms = []; for (let i = 0; i + W <= d.length; i += W) { let q = 0; for (let j = i; j < i + W; j++) q += d[j] * d[j]; rms.push(Math.sqrt(q / W)); }
          const pk = Math.max(...rms); ctx.close();
          const at = t => { const v = rms[Math.round(t / 0.05) - 1]; return v > 0 ? (20 * Math.log10(v / pk)).toFixed(0).padStart(4) : '-inf'; };
          return b.duration.toFixed(1) + 's          ' + [0.05, 0.1, 0.15, 0.2, 0.3, 0.5, 1].map(at).join(' ') + '       ' + pk.toFixed(3);
        } catch (e) { return 'ERR ' + e.message; }
      })()`);
      console.log(inst.padEnd(18).slice(0, 18), note.padEnd(4), r);
    }
  } catch (e) { console.log('ERR', e.message); }
  await page.close();
})();
